const storageKey = 'agent-hub-language';

export function editorTranslation(
  language: Language,
  key: string,
  defaultValue: string,
  interpolations: Record<string, unknown> = {}
) {
  const template = language === 'zh-CN' ? editorZh[key] ?? defaultValue : defaultValue;
  return template.replace(/\{\{(\w+)\}\}/g, (_, name: string) => String(interpolations[name] ?? ''));
}

function initialLanguage(): Language {
  let stored: string | null = null;
  try { stored = localStorage.getItem(storageKey); } catch { /* Storage can be unavailable in hardened browsers. */ }
  if (stored === 'en' || stored === 'zh-CN') return stored;
  return navigator.language.toLowerCase().startsWith('zh') ? 'zh-CN' : 'en';
}

type I18nValue = { language: Language; setLanguage: (language: Language) => void; t: (key: TranslationKey) => string; locale: string };
const I18nContext = createContext<I18nValue | null>(null);

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [language, setLanguageState] = useState<Language>(initialLanguage);
  const languageRef = useRef(language);
  languageRef.current = language;
  const t = useCallback((key: TranslationKey) => dictionaries[languageRef.current][key], []);
  useEffect(() => { document.documentElement.lang = language; }, [language]);
  const value = useMemo<I18nValue>(() => ({
    language,
    setLanguage(next) {
      try { localStorage.setItem(storageKey, next); } catch { /* Language still changes for this session. */ }
      setLanguageState(next);
    },
    t,
    locale: language === 'zh-CN' ? 'zh-CN' : 'en-US'
  }), [language, t]);
  return React.createElement(I18nContext.Provider, { value }, children);
}

export function useI18n() {
  const value = useContext(I18nContext);
  if (!value) throw new Error('useI18n must be used inside I18nProvider');
  return value;
}
